#!/usr/bin/env python3
"""Genera study-question-bank.en.json (traduccion al ingles) a partir del
banco en espanol study-question-bank.json.

Estrategia segura: se COPIA la estructura del banco espanol (ids, keys,
correctOptionKey/Id, topicId, order, tags) y solo se SUPERPONE el texto en
ingles. Asi es imposible desalinear la respuesta correcta al traducir.

- BASE[order]  -> traduccion de las 60 preguntas originales (prompt, opciones
  por key A-D, justification).
- RW[sourceOrder] -> traduccion de los 60 enunciados reformulados (solo prompt;
  las opciones y la justificacion se reutilizan de la pregunta base en ingles).

answer.text se deriva automaticamente del texto ingles de la opcion correcta.

Uso:  python build-en-bank.py   (luego  python build-questions.py)
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(HERE, "study-question-bank.json")
OUT = os.path.join(HERE, "study-question-bank.en.json")
VARIANT_TAG = "variant_reworded"

TITLE_EN = "Claude Code Study Question Bank"
DESC_EN = "Multiple-choice study bank for Claude Code and Claude development workflows."

TOPIC_TITLES = {
    "01KT81BA4J1SN6A5M3D93T1920": "Claude Code for Continuous Integration",
    "01KT81BA4JK0BAMH84VBFJK0FA": "Multi-Agent Research System",
    "01KT81BA4J2675N47R42Q4C716": "Developer Productivity with Claude",
    "01KT81BA4JJHS623EN20YJ4JZ1": "Code Generation with Claude Code",
    "01KT81BA4JCST5PP0RTAGENT01": "Customer Support Resolution Agent",
    "01KT81BA4JXTRCTDATA5CHMA01": "Structured Data Extraction",
}

SCENARIOS = {
    "01KT81BA4J1SN6A5M3D93T1920": "You are integrating Claude Code into your Continuous Integration/Continuous Deployment (CI/CD) pipeline. The system runs automated code reviews, generates test cases, and provides feedback on pull requests. You must design prompts that deliver actionable feedback and minimize false positives.",
    "01KT81BA4JK0BAMH84VBFJK0FA": "You are building a multi-agent research system using the Claude Agent SDK. A coordinator agent delegates to specialized subagents: one searches the web, one analyzes documents, one synthesizes findings, and one generates reports. The system researches topics and produces comprehensive reports with citations.",
    "01KT81BA4J2675N47R42Q4C716": "You are building developer productivity tools using the Claude Agent SDK. The agent helps engineers explore unfamiliar codebases, understand legacy systems, generate boilerplate code, and automate repetitive tasks. It uses the built-in tools (Read, Write, Bash, Grep, Glob) and integrates with Model Context Protocol (MCP) servers.",
    "01KT81BA4JJHS623EN20YJ4JZ1": "You are using Claude Code to accelerate software development. Your team uses it for code generation, refactoring, debugging, and documentation. You need to integrate it into your development workflow with custom slash commands, CLAUDE.md configurations, and an understanding of when to use plan mode versus direct execution.",
    "01KT81BA4JCST5PP0RTAGENT01": "You are building a customer support resolution agent with the Claude Agent SDK. The agent uses MCP tools (get_customer, lookup_order, process_refund, escalate_to_human) to resolve customer inquiries, aiming to resolve 80%+ on first contact while knowing when to escalate to a human.",
    "01KT81BA4JXTRCTDATA5CHMA01": "You are building a structured data extraction system that processes unstructured documents (invoices, contracts, reports) and produces output validated against JSON schemas. You must handle varied formats, missing fields, and edge cases while maintaining reliability.",
}

