def main():
    with open(SRC, encoding="utf-8") as f:
        data = json.load(f)

    out = {
        "id": data.get("id"),
        "contractId": data.get("contractId"),
        "schemaVersion": data.get("schemaVersion"),
        "title": TITLE_EN,
        "description": DESC_EN,
        "language": "en",
        "version": data.get("version"),
        "topics": [],
        "questions": [],
    }
    for t in data["topics"]:
        tt = dict(t)
        tt["title"] = TOPIC_TITLES.get(t["id"], t["title"])
        out["topics"].append(tt)

    missing = []
    for q in data["questions"]:
        meta = q.get("studyMetadata", {})
        is_variant = VARIANT_TAG in meta.get("tags", [])
        source_order = meta.get("sourceOrder") if is_variant else q["order"]

        base = BASE.get(source_order)
        if base is None:
            missing.append(source_order)
            continue

        # Enunciado: variante usa RW; original usa base['p'].
        if is_variant:
            prompt_en = RW.get(source_order)
            if prompt_en is None:
                missing.append(("RW", source_order))
                continue
        else:
            prompt_en = base["p"]

        correct_key = q["answer"]["correctOptionKey"]
        options_en = []
        correct_text = ""
        for o in q["options"]:
            text_en = base.get(o["key"], o.get("text", ""))
            options_en.append({"id": o["id"], "key": o["key"], "text": text_en})
            if o["key"] == correct_key:
                correct_text = text_en

        nq = {
            "id": q["id"],
            "topicId": q["topicId"],
            "order": q["order"],
            "type": q.get("type", "multiple_choice"),
            "scenario": {
                "title": TOPIC_TITLES.get(q["topicId"], q["scenario"].get("title", "")),
                "body": SCENARIOS.get(q["topicId"], q["scenario"].get("body", "")),
            },
            "prompt": prompt_en,
            "options": options_en,
            "answer": {
                "correctOptionId": q["answer"]["correctOptionId"],
                "correctOptionKey": correct_key,
                "text": correct_text,
                "justification": base["j"],
            },
            "studyMetadata": dict(meta),
        }
        out["questions"].append(nq)

    if missing:
        raise SystemExit(f"Faltan traducciones para: {missing}")

    with open(OUT, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=2)

    print(f"OK: {len(out['questions'])} preguntas EN -> {OUT}")


if __name__ == "__main__":
    main()
